   740  static int dist_cache_touch(struct rar5* rar, int index) {
   741      int* q = rar->cstate.dist_cache;
   742      int i, dist = q[index];
   743
   744      for(i = index; i > 0; i--)
   745          q[i] = q[i - 1];
   746
   747      q[0] = dist;
   748      return dist;
   749  }
